using VisualRelay.Core.Configuration;

namespace VisualRelay.Tests;

public sealed partial class BackendConfigGeneratorTests
{
    // ── Vision tier: pinned upstream models ───────────────────────────────

    /// <summary>
    /// The hf-qwen3-vl-235b entry must use auto-routed HF
    /// (no pinned provider segment) so the HF router picks a live
    /// Inference Provider.  Pinned novita was confirmed broken
    /// 2026-07-07.
    /// </summary>
    [Fact]
    public void VisionVL_235b_UpstreamModel_IsAutoRouted()
    {
        var yaml = File.ReadAllText(TemplatePath);
        var upstream = ParseUpstreamModel(yaml, "hf-qwen3-vl-235b");

        Assert.NotNull(upstream);
        Assert.Equal("huggingface/Qwen/Qwen3-VL-235B-A22B-Instruct", upstream);
    }

    /// <summary>
    /// The hf-qwen3-vl-30b entry must use auto-routed HF (no pinned
    /// provider segment).  Pinned deepinfra was confirmed broken
    /// 2026-07-07 (litellm.APIError: Model not supported for provider).
    /// </summary>
    [Fact]
    public void VisionVL_30b_UpstreamModel_IsAutoRouted()
    {
        var yaml = File.ReadAllText(TemplatePath);
        var upstream = ParseUpstreamModel(yaml, "hf-qwen3-vl-30b");

        Assert.NotNull(upstream);
        Assert.Equal("huggingface/Qwen/Qwen3-VL-30B-A3B-Instruct", upstream);
    }

    // ── Vision tier: chain members are all vision-capable ─────────────────

    /// <summary>
    /// Every model in the vision chain must be a vision model — no text
    /// coder may appear as a fallback.  Broken vision routes must surface
    /// as API errors, not silent text-model answers.
    /// </summary>
    [Fact]
    public void VisionChain_EveryEntryIsVisionCapable()
    {
        var chain = BackendConfigGenerator.Chains["vision"];

        // Canonical vision models (the only allowed entries).
        string[] visionModels = ["hf-qwen3-vl-235b", "hf-qwen3-vl-30b"];

        // Exact membership: every entry must be a known VL model.
        foreach (var (model, _) in chain)
            Assert.Contains(model, visionModels);

        // And every VL model must appear exactly once.
        var chainModels = chain.Select(c => c.Model).ToHashSet();
        foreach (var vm in visionModels)
            Assert.True(chainModels.Contains(vm),
                $"vision chain must include '{vm}'");

        // The chain must NOT contain kimi-k2 or the fallback alias.
        Assert.DoesNotContain("kimi-k2", chainModels);
        Assert.DoesNotContain("fallback", chainModels);
    }

    // ── Vision tier: selectable models are all vision-capable ─────────────

    /// <summary>
    /// Every model in the vision selectable list must be vision-capable.
    /// Users must never be offered a text-only model as a "vision" choice.
    /// </summary>
    [Fact]
    public void VisionSelectable_EveryEntryIsVisionCapable()
    {
        var selectable = BackendConfigGenerator.SelectableModelsByTier["vision"];

        // Only these two VL models are allowed.
        string[] visionModels = ["hf-qwen3-vl-235b", "hf-qwen3-vl-30b"];

        foreach (var model in selectable)
            Assert.Contains(model, visionModels);

        Assert.Equal(2, selectable.Count);
        Assert.Contains("hf-qwen3-vl-235b", selectable);
        Assert.Contains("hf-qwen3-vl-30b", selectable);
        Assert.DoesNotContain("kimi-k2", selectable);
    }

    // ── Vision tier: generated config shape ───────────────────────────────

    /// <summary>
    /// With HF_TOKEN present, the vision fallback chain must be exactly
    /// [hf-qwen3-vl-30b] — no text-model or fallback-tier entries.
    /// </summary>
    [Fact]
    public void VisionFallback_DoesNotContainFallbackOrKimi()
    {
        var present = new HashSet<string> { "HF_TOKEN" };
        var fallbacks = GeneratedFallbacks(present);

        Assert.True(fallbacks.TryGetValue("vision", out var chain));
        Assert.Equal(["hf-qwen3-vl-30b"], chain);
    }

    /// <summary>
    /// With all keys present, the vision fallback chain still must not
    /// include fallback or kimi-k2.
    /// </summary>
    [Fact]
    public void VisionFallback_AllKeysPresent_StillNoTextModels()
    {
        var present = new HashSet<string>
        {
            "HF_TOKEN", "DEEPSEEK_API_KEY", "MOONSHOT_API_KEY",
            "ANTHROPIC_API_KEY", "OPENAI_API_KEY",
        };
        var fallbacks = GeneratedFallbacks(present);

        Assert.True(fallbacks.TryGetValue("vision", out var chain));
        Assert.Equal(["hf-qwen3-vl-30b"], chain);
    }

    /// <summary>
    /// When HF_TOKEN is absent (no vision keys available), the vision
    /// tier must be omitted from aliases entirely — a vision request
    /// surfaces as a model-not-found error, not a silent text-model
    /// answer.
    /// </summary>
    [Fact]
    public void VisionOmitted_WhenNoHfToken()
    {
        var present = new HashSet<string> { "DEEPSEEK_API_KEY", "MOONSHOT_API_KEY" };
        var aliases = GeneratedAliases(present);

        Assert.False(aliases.ContainsKey("vision"),
            "vision tier must be omitted when HF_TOKEN is absent");
    }
}

